package notification.core.artifact;import java.util.Map;import java.util.concurrent.ConcurrentHashMap;import java.util.function.Supplier;/** * Stores notification artifacts in a type-safe manner. * * Examples of artifacts: * - TemplateContext * - PersonalizationArtifact * - EmailPayloadArtifact * - RetryArtifact * * Artifacts are stored using their class as the key. */public class ArtifactStore {    private final Map<Class<? extends Artifact>, Artifact> store =            new ConcurrentHashMap<>();    /**     * Stores an artifact.     *     * @param artifact artifact to store     */    public void put(Artifact artifact) {        if (artifact == null) {            throw new IllegalArgumentException(                    "Artifact cannot be null"            );        }        store.put(artifact.getClass(), artifact);    }    /**     * Retrieves an artifact by its type.     *     * @param type artifact class     * @param <T> artifact type     * @return stored artifact, or null if not present     */    public <T extends Artifact> T get(Class<T> type) {        Artifact artifact = store.get(type);        if (artifact == null) {            return null;        }        return type.cast(artifact);    }    /**     * Retrieves an artifact if present; otherwise creates,     * stores and returns the default artifact.     *     * @param type artifact class     * @param defaultSupplier supplier used to create the default artifact     * @param <T> artifact type     * @return existing or newly created artifact     */    public <T extends Artifact> T getOrDefault(            Class<T> type,            Supplier<T> defaultSupplier) {        Artifact artifact = store.computeIfAbsent(                type,                key -> defaultSupplier.get()        );        return type.cast(artifact);    }    /**     * Checks whether an artifact exists.     *     * @param type artifact class     * @param <T> artifact type     * @return true if artifact exists     */    public <T extends Artifact> boolean contains(Class<T> type) {        return store.containsKey(type);    }    /**     * Removes an artifact.     *     * @param type artifact class     * @param <T> artifact type     * @return removed artifact, or null     */    public <T extends Artifact> T remove(Class<T> type) {        Artifact artifact = store.remove(type);        if (artifact == null) {            return null;        }        return type.cast(artifact);    }    /**     * Removes all stored artifacts.     */    public void clear() {        store.clear();    }    /**     * Returns the number of stored artifacts.     *     * @return artifact count     */    public int size() {        return store.size();    }}